import Foundation

/// Port of the stable SciPy audio detector in `research/src/tennis_clips/detector.py`.
///
/// The coefficients are generated by `scipy.signal.butter(4, band,
/// btype: "bandpass", fs: 16_000, output: "sos")` and `sosfilt_zi`.
public struct ImpactSignalDetector: Sendable {
    public struct Config: Sendable {
        public var sampleRate = 16_000
        public var analysisRate = 200
        public var amplitudePercentile = 98.5
        public var minimumEventDistance = 0.7
        public var minimumMidEnergyRatio = 0.07
        public var maximumHighEnergyRatio = 0.35

        public init() {}
    }

    public struct Candidate: Equatable, Sendable {
        public let time: TimeInterval
        public let amplitude: Double
        public let threshold: Double
        public let midEnergyRatio: Double
        public let highEnergyRatio: Double
    }

    private struct Section: Sendable {
        let b0: Double
        let b1: Double
        let b2: Double
        let a1: Double
        let a2: Double
        let z1: Double
        let z2: Double
    }

    private struct Band: Sendable {
        let sections: [Section]
    }

    public let config: Config

    public init(config: Config = Config()) {
        precondition(config.sampleRate == 16_000, "The parity coefficients require 16 kHz audio")
        self.config = config
    }

    public func candidates(samples: [Float]) -> [Candidate] {
        guard samples.count > 55 else { return [] }

        let full = envelope(samples: samples, band: Self.fullBand)
        let mid = envelope(samples: samples, band: Self.midBand)
        let high = envelope(samples: samples, band: Self.highBand)
        guard !full.isEmpty, full.count == mid.count, mid.count == high.count else { return [] }

        let threshold = percentile(full, percentile: config.amplitudePercentile)
        let minimumDistance = Int((config.minimumEventDistance * Double(config.analysisRate)).rounded())
        let peakIndexes = findPeaks(
            full,
            minimumHeight: threshold,
            minimumDistance: minimumDistance,
            minimumProminence: threshold * 0.5
        )

        return peakIndexes.compactMap { index in
            let amplitude = max(full[index], 1e-9)
            let midRatio = pow(mid[index] / amplitude, 2)
            let highRatio = pow(high[index] / amplitude, 2)
            guard midRatio >= config.minimumMidEnergyRatio,
                  highRatio <= config.maximumHighEnergyRatio
            else { return nil }

            return Candidate(
                time: Double(index) / Double(config.analysisRate),
                amplitude: amplitude,
                threshold: threshold,
                midEnergyRatio: midRatio,
                highEnergyRatio: highRatio
            )
        }
    }

    private func envelope(samples: [Float], band: Band) -> [Double] {
        var filtered = oddExtension(samples, edge: 27)
        filterInPlace(&filtered, sections: band.sections, initialScale: filtered[0])
        filtered.reverse()
        filterInPlace(&filtered, sections: band.sections, initialScale: filtered[0])
        filtered.reverse()

        let edge = 27
        let signalCount = samples.count
        let windowSize = max(1, Int((Double(config.sampleRate) * 0.008).rounded()))
        let leftRadius = windowSize / 2
        let rightRadius = windowSize - leftRadius - 1
        let step = max(1, Int((Double(config.sampleRate) / Double(config.analysisRate)).rounded()))
        var result: [Double] = []
        result.reserveCapacity((signalCount + step - 1) / step)

        // sqrt(convolve(filtered², flat(128), mode: "same"))[::80].
        // Only the requested 200 Hz samples are materialized to reduce memory use.
        for center in stride(from: 0, to: signalCount, by: step) {
            let lower = max(0, center - leftRadius)
            let upper = min(signalCount - 1, center + rightRadius)
            var sum = 0.0
            for index in lower...upper {
                let value = filtered[index + edge]
                sum += value * value
            }
            result.append(sqrt(sum / Double(windowSize)))
        }
        return result
    }

    private func oddExtension(_ samples: [Float], edge: Int) -> [Double] {
        precondition(samples.count > edge)
        var extended = [Double](repeating: 0, count: samples.count + edge * 2)
        let first = Double(samples[0])
        let last = Double(samples[samples.count - 1])

        for index in 0..<edge {
            extended[index] = 2 * first - Double(samples[edge - index])
        }
        for index in samples.indices {
            extended[index + edge] = Double(samples[index])
        }
        for index in 0..<edge {
            extended[edge + samples.count + index] = 2 * last - Double(samples[samples.count - 2 - index])
        }
        return extended
    }

    private func filterInPlace(
        _ values: inout [Double],
        sections: [Section],
        initialScale: Double
    ) {
        for section in sections {
            var state1 = section.z1 * initialScale
            var state2 = section.z2 * initialScale
            for index in values.indices {
                let input = values[index]
                let output = section.b0 * input + state1
                state1 = section.b1 * input - section.a1 * output + state2
                state2 = section.b2 * input - section.a2 * output
                values[index] = output
            }
        }
    }

    private func percentile(_ values: [Double], percentile: Double) -> Double {
        let sorted = values.sorted()
        guard let only = sorted.first else { return 0 }
        guard sorted.count > 1 else { return only }
        let position = Double(sorted.count - 1) * percentile / 100
        let lower = Int(floor(position))
        let upper = Int(ceil(position))
        let fraction = position - Double(lower)
        return sorted[lower] + (sorted[upper] - sorted[lower]) * fraction
    }

    private func findPeaks(
        _ values: [Double],
        minimumHeight: Double,
        minimumDistance: Int,
        minimumProminence: Double
    ) -> [Int] {
        guard values.count >= 3 else { return [] }
        var localPeaks: [Int] = []
        var index = 1

        // SciPy represents a flat peak by the middle sample, rounded down.
        while index < values.count - 1 {
            guard values[index - 1] < values[index] else {
                index += 1
                continue
            }
            var rightEdge = index
            while rightEdge + 1 < values.count, values[rightEdge + 1] == values[index] {
                rightEdge += 1
            }
            if rightEdge + 1 < values.count,
               values[rightEdge] > values[rightEdge + 1],
               values[index] >= minimumHeight {
                localPeaks.append((index + rightEdge) / 2)
            }
            index = rightEdge + 1
        }

        // scipy.signal.find_peaks applies distance before prominence. Higher peaks win.
        let priorityOrder = localPeaks.indices.sorted {
            if values[localPeaks[$0]] == values[localPeaks[$1]] { return $0 > $1 }
            return values[localPeaks[$0]] > values[localPeaks[$1]]
        }
        var retained = [Bool](repeating: true, count: localPeaks.count)
        for priorityIndex in priorityOrder where retained[priorityIndex] {
            let selected = localPeaks[priorityIndex]
            for otherIndex in localPeaks.indices where retained[otherIndex] && otherIndex != priorityIndex {
                if abs(localPeaks[otherIndex] - selected) < minimumDistance {
                    retained[otherIndex] = false
                }
            }
        }

        return localPeaks.indices.compactMap { peakIndex in
            guard retained[peakIndex] else { return nil }
            let peak = localPeaks[peakIndex]
            let height = values[peak]
            var leftMinimum = height
            var cursor = peak
            while cursor >= 0, values[cursor] <= height {
                leftMinimum = min(leftMinimum, values[cursor])
                cursor -= 1
            }
            var rightMinimum = height
            cursor = peak
            while cursor < values.count, values[cursor] <= height {
                rightMinimum = min(rightMinimum, values[cursor])
                cursor += 1
            }
            let prominence = height - max(leftMinimum, rightMinimum)
            return prominence >= minimumProminence ? peak : nil
        }
    }

    private static let fullBand = Band(sections: [
        Section(b0: 0.7420434859024201, b1: 1.4840869718048402, b2: 0.7420434859024201, a1: 1.6612958431214457, a2: 0.6940169382407124, z1: 0.14257566498481528, z2: 0.12810281129456222),
        Section(b0: 1, b1: 2, b2: 1, a1: 1.8255448495100886, a2: 0.8613419770425558, z1: 0.07512731544450417, z2: 0.05794923211744815),
        Section(b0: 1, b1: -2, b2: 1, a1: -1.9425131629847214, a2: 0.9434772385780453, z1: -0.9597464663316218, z2: 0.9597464663316284),
        Section(b0: 1, b1: -2, b2: 1, a1: -1.9753201768232749, a2: 0.9762962394835808, z1: 0, z2: 0),
    ])

    private static let midBand = Band(sections: [
        Section(b0: 0.10956221555910728, b1: 0.21912443111821456, b2: 0.10956221555910728, a1: 0.1698145650652418, a2: 0.06721764903511308, z1: 0.24471219802611238, z2: 0.08574872236461549),
        Section(b0: 1, b1: 2, b2: 1, a1: 0.44450211524069905, a2: 0.52324414990885, z1: 0.3658883835390218, z2: -0.022546556992033714),
        Section(b0: 1, b1: -2, b2: 1, a1: -1.5506760117283023, a2: 0.6115556287930594, z1: -0.7201627971242414, z2: 0.7201627971242414),
        Section(b0: 1, b1: -2, b2: 1, a1: -1.8024004588964848, a2: 0.8556194023502908, z1: 0, z2: 0),
    ])

    private static let highBand = Band(sections: [
        Section(b0: 0.29203835088768826, b1: -0.5840767017753765, b2: 0.29203835088768826, a1: -0.9026745014079105, a2: 0.23344463809173865, z1: -0.29203835088768804, z2: 0.2920383508876882),
        Section(b0: 1, b1: -2, b2: 1, a1: -1.2250848044164377, a2: 0.6196597921018026, z1: 0, z2: 0),
        Section(b0: 1, b1: 2, b2: 1, a1: 1.6446471846250257, a2: 0.6813548542909653, z1: 0, z2: 0),
        Section(b0: 1, b1: 2, b2: 1, a1: 1.831384024651316, a2: 0.8679556245595783, z1: 0, z2: 0),
    ])
}
